CREATE OR ALTER PROCEDURE [dbo].[uspCustomerContact_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @FullName NVARCHAR(MAX) = NULL
	, @Position NVARCHAR(MAX) = NULL
	, @Phone NVARCHAR(MAX) = NULL
	, @Email NVARCHAR(MAX) = NULL
	, @IsPrimary BIT = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, t.[Name]
			, t.[Position]
			, t.[Phone]
			, t.[Email]
			, t.[IsPrimary]
			, t.[Status]
			, t.[Note]
			, t.[FullName]
			, t.[CreatedDate]
		FROM [dbo].[CustomerContact] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[FullName] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@FullName, '') = '' OR t.[FullName] LIKE CONCAT('%', @FullName, '%'))
			AND (ISNULL(@Position, '') = '' OR t.[Position] LIKE CONCAT('%', @Position, '%'))
			AND (ISNULL(@Phone, '') = '' OR t.[Phone] LIKE CONCAT('%', @Phone, '%'))
			AND (ISNULL(@Email, '') = '' OR t.[Email] LIKE CONCAT('%', @Email, '%'))
			AND (@IsPrimary IS NULL OR t.[IsPrimary] = @IsPrimary)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'position' THEN r.[Position] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'position' THEN r.[Position] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'phone' THEN r.[Phone] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'phone' THEN r.[Phone] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'email' THEN r.[Email] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'email' THEN r.[Email] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'isPrimary' THEN r.[IsPrimary] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'isPrimary' THEN r.[IsPrimary] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'fullName' THEN r.[FullName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'fullName' THEN r.[FullName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
